FUNCTION_BLOCK FB
VAR_INPUT
    enqueue : BOOL;
    dequeue : BOOL;
    reset : BOOL;
    capacity : DINT;
END_VAR
VAR_OUTPUT
    elementCount : DINT;
    status : WORD;
END_VAR
VAR_IN_OUT
    item : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR
VAR
    enqueue_prev : BOOL;
    dequeue_prev : BOOL;
    enqueue_rising : BOOL;
    dequeue_rising : BOOL;
    head : DINT := 1;
    tail : DINT := 1;
    internalCount : DINT := 0;
END_VAR

status := 16#0000;

enqueue_rising := enqueue AND NOT enqueue_prev;
dequeue_rising := dequeue AND NOT dequeue_prev;

IF reset THEN
    internalCount := 0;
    head := 1;
    tail := 1;
ELSIF NOT (enqueue_rising AND dequeue_rising) THEN
    IF enqueue_rising THEN
        IF internalCount < capacity THEN
            buffer[tail] := item;
            tail := tail + 1;
            IF tail > capacity THEN
                tail := 1;
            END_IF;
            internalCount := internalCount + 1;
        ELSE
            status := 16#8002;
        END_IF;
    END_IF;

    IF dequeue_rising THEN
        IF internalCount > 0 THEN
            item := buffer[head];
            head := head + 1;
            IF head > capacity THEN
                head := 1;
            END_IF;
            internalCount := internalCount - 1;
        ELSE
            status := 16#8001;
        END_IF;
    END_IF;
END_IF;

elementCount := internalCount;

enqueue_prev := enqueue;
dequeue_prev := dequeue;
END_FUNCTION_BLOCK
